import copy
from taf.rfrl.utilities.robot.parallel_runner import run_parallel_in_robot
from taf.rfrl.utilities.tl_config import tl


def run_parallel_on_all_btses(gnb_function, enb_function, gnb_function_kwargs=None, enb_function_kwargs=None,
                              gnb_ids=None, enb_ids=None):
    """
    Run the given functions on all GNBs and ENBs in parallel.
    :param gnb_function: Function to run on GNBs.
    :param enb_function: Function to run on ENBs.
    :param gnb_function_kwargs: Keyword arguments for the GNB function.
    :param enb_function_kwargs: Keyword arguments for the ENB function.
    :param gnb_ids: List of GNB IDs to run the function on - if not passed then run on all available in configuration
    :param enb_ids: List of ENB IDs to run the function on - if not passed then run on all available in configuration
    :return: Dictionary with the results of the functions. eg:
    {
        'GNB0': '/tmp/Snapshot_REST_GNB0_DU0_77135_77135_SBTS24R3_ENB_9999_240521_000009_20240522-093026.zip',
        'GNB1': '/tmp/Snapshot_REST_GNB1_DU0_77088_77088_SBTS24R3_ENB_9999_240521_000009_20240522-093026.zip'
    }
    """
    list_of_functions = build_list_of_functions_for_all_btses(gnb_function, enb_function,
                                                              gnb_function_kwargs, enb_function_kwargs,
                                                              gnb_ids, enb_ids)
    raw_results = run_parallel_in_robot(list_of_functions)
    results = {name.split("::")[1]: raw_results[name] for name in raw_results.keys()}
    return results


def build_list_of_functions_for_all_btses(gnb_function, enb_function,
                                          gnb_function_kwargs=None, enb_function_kwargs=None,
                                          gnb_ids=None, enb_ids=None):
    """
    Build a list of functions to run on all GNBs and ENBs.
    :param gnb_function: Function to run on GNBs.
    :param enb_function: Function to run on ENBs.
    :param gnb_function_kwargs: Keyword arguments for the GNB function.
    :param enb_function_kwargs: Keyword arguments for the ENB function.
    :param gnb_ids: List of GNB IDs to run the function on - if not passed then run on all available in configuration
    :param enb_ids: List of ENB IDs to run the function on - if not passed then run on all available in configuration
    :return: List of functions to run on all GNBs and ENBs eg:
      [
        {
            'function': <function1>,
            'function_kwargs': <function_kwargs1>,
            'device_name': 'GNB0',
        },
        {
            'function': <function2>,
            'function_kwargs': <function_kwargs2>,
            'device_name': 'ENB0',
        },
    ]

    """
    list_of_functions = []
    gnb_function_kwargs = gnb_function_kwargs or {}
    enb_function_kwargs = enb_function_kwargs or {}

    if gnb_ids is None:
        gnb_ids = range(len(tl.gnbs)) if tl.gnbs else []
    if enb_ids is None:
        enb_ids = range(len(tl.enbs)) if tl.enbs else []

    for gnb_id in gnb_ids:
        kwargs = copy.copy(gnb_function_kwargs)
        kwargs['bts_id'] = gnb_id
        list_of_functions.append({
            'function': gnb_function,
            'function_kwargs': kwargs,
            'device_name': "GNB{}".format(gnb_id)
        })

    for enb_id in enb_ids:
        kwargs = copy.copy(enb_function_kwargs)
        kwargs['bts_id'] = enb_id
        list_of_functions.append({
            'function': enb_function,
            'function_kwargs': kwargs,
            'device_name': "ENB{}".format(enb_id)
        })
    return list_of_functions
